@dataclass
class DownloadedVideo:
    """A video that has been downloaded to a local path."""

    video_path: Path
    source_url: str
    platform: str
    video_id: str = ""
    title: str = ""
    duration: float | None = None
    thumbnail: str | None = None
    warnings: list[str] = field(default_factory=list)


def _duration_seconds(raw: object) -> float | None:
    """Platform APIs usually report duration in milliseconds."""
    try:
        return float(raw) / 1000.0  # type: ignore[arg-type]
    except (TypeError, ValueError):
        return None


# ---------------------------------------------------------------------------
# configuration helpers
# ---------------------------------------------------------------------------


def _download_dir() -> Path:
    env_dir = os.getenv("DOWNLOAD_DIR", "").strip()
    raw = env_dir or str(config_get("download.download_dir", "./downloads") or "./downloads")
    path = Path(raw).expanduser()
    path.mkdir(parents=True, exist_ok=True)
    return path


def _proxy_url() -> str | None:
    env_proxy = os.getenv("DOWNLOAD_PROXY", "").strip()
    if env_proxy:
        return env_proxy
    configured = str(config_get("download.proxy", "") or "").strip()
    if configured:
        return configured
    for key in (
        "HTTPS_PROXY",
        "https_proxy",
        "HTTP_PROXY",
        "http_proxy",
        "ALL_PROXY",
        "all_proxy",
    ):
        value = os.getenv(key, "").strip()
        if value:
            return value
    return None


def _client_proxy_kwargs() -> dict:
    """httpx.Client kwargs for the configured download proxy (if any)."""
    proxy = _proxy_url()
    return {"proxies": proxy} if proxy else {}


def _platform_env(platform: str, *keys: str) -> str:
    for key in keys:
        value = os.getenv(key, "").strip()
        if value:
            return value
    return ""


def _parse_cookie_string(raw_cookie: str) -> dict[str, str]:
    cookies: dict[str, str] = {}
    for part in raw_cookie.split(";"):
        if "=" in part:
            key, value = part.strip().split("=", 1)
            if key:
                cookies[key] = value
    return cookies


def _write_netscape_cookie_file(cookies: dict[str, str], domain: str) -> Path:
    """Write a temporary Netscape cookie file for yt-dlp."""
    domain_field = domain if domain.startswith(".") else f".{domain}"
    expiry = int(time.time()) + 365 * 24 * 3600
    lines = ["# Netscape HTTP Cookie File"]
    for name, value in cookies.items():
        lines.append(
            f"{domain_field}\tTRUE\t/\tFALSE\t{expiry}\t{name}\t{value}"
        )
    fd, name = tempfile.mkstemp(prefix="framelearn_cookies_", suffix=".txt")
    with os.fdopen(fd, "w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")
    return Path(name)


def _cleanup(paths: list[Path]) -> None:
    for path in paths:
        try:
            path.unlink(missing_ok=True)
        except OSError:
            pass


# ---------------------------------------------------------------------------
# generic yt-dlp downloader (Bilibili / YouTube / fallbacks)
# ---------------------------------------------------------------------------

_YTDLP_FORMATS = {
    "youtube": "bv*[ext=mp4]+ba[ext=m4a]/b[ext=mp4]/bestvideo+bestaudio/best",
    "bilibili": "bv*[ext=mp4]/bestvideo+bestaudio/best",
    "douyin": "bestvideo+bestaudio/best",
    "kuaishou": "bestvideo+bestaudio/best",
}


def _configured_cookie_file(platform: str, cleanup_paths: list[Path]) -> Path | None:
    raw_cookie = _platform_env(
        platform,
        f"{platform.upper()}_COOKIE",
        f"{platform.upper()}_COOKIE_FILE",
    )
    if not raw_cookie:
        return None

    candidate = Path(raw_cookie).expanduser()
    if candidate.is_file():
        return candidate

    cookies = _parse_cookie_string(raw_cookie)
    if not cookies:
        return None
    path = _write_netscape_cookie_file(cookies, _cookie_domain(platform))
    cleanup_paths.append(path)
    return path


def _cookie_domain(platform: str) -> str:
    return {
        "youtube": ".youtube.com",
        "bilibili": ".bilibili.com",
        "douyin": ".douyin.com",
        "kuaishou": ".kuaishou.com",
    }.get(platform, ".example.com")


def _ytdlp_options(
    platform: str,
    output_dir: Path,
    cookiefile: Path | None = None,
) -> dict:
    proxy = _proxy_url()
    opts: dict = {
        "format": _YTDLP_FORMATS.get(platform, "bestvideo+bestaudio/best"),
        "outtmpl": str(output_dir / "%(id)s.%(ext)s"),
        "noplaylist": True,
        "merge_output_format": "mp4",
        "noprogress": True,
        "quiet": False,
        "overwrites": False,
        "retries": 5,
        "fragment_retries": 5,
    }
    if proxy:
        opts["proxy"] = proxy
    if cookiefile:
        opts["cookiefile"] = str(cookiefile)
    if platform == "bilibili":
        opts["http_headers"] = {"Referer": "https://www.bilibili.com"}
    return opts


def _existing_file(output_dir: Path, video_id: str) -> Path | None:
    if not video_id:
        return None
    for ext in (".mp4", ".mkv", ".webm", ".mov", ".flv"):
        candidate = output_dir / f"{video_id}{ext}"
        if candidate.exists() and candidate.stat().st_size > 0:
            return candidate
    return None


def _locate_downloaded_file(output_dir: Path, video_id: str) -> Path | None:
    existing = _existing_file(output_dir, video_id)
    if existing:
        return existing

    candidates = sorted(
        output_dir.glob(f"{video_id}.*"),
        key=lambda p: p.stat().st_mtime,
        reverse=True,
    )
    excluded_suffixes = (".part", ".ytdl", ".temp", ".info.json", ".description")
    video_extensions = (".mp4", ".mkv", ".webm", ".mov", ".flv", ".m4v")
    for candidate in candidates:
        if candidate.suffix.lower() in excluded_suffixes or candidate.stat().st_size <= 0:
            continue
        if candidate.suffix.lower() in video_extensions:
            return candidate
    return None


def _download_with_ytdlp(
    url: str,
    platform: str,
    output_dir: Path,
    cookiefile: Path | None = None,
) -> DownloadedVideo:
    cleanup_paths: list[Path] = []
    if cookiefile is None:
        cookiefile = _configured_cookie_file(platform, cleanup_paths)

    opts = _ytdlp_options(platform, output_dir, cookiefile=cookiefile)
    try:
        with yt_dlp.YoutubeDL(opts) as ydl:
            info = ydl.extract_info(url, download=True)
    finally:
        _cleanup(cleanup_paths)

    if info and info.get("_type") == "playlist" and info.get("entries"):
        info = info["entries"][0]

    video_id = str(info.get("id") or extract_video_id(url, platform) or "")
    video_path = _locate_downloaded_file(output_dir, video_id)
    if video_path is None:
        raise DownloadError(
            f"{platform} 视频下载完成，但未找到输出文件（video_id={video_id}）"
        )
    return DownloadedVideo(
        video_path=video_path,
        source_url=url,
        platform=platform,
        video_id=video_id,
        title=str(info.get("title") or ""),
        duration=float(info["duration"]) if info.get("duration") else None,
        thumbnail=info.get("thumbnail"),
    )


# ---------------------------------------------------------------------------
# Bilibili
# ---------------------------------------------------------------------------


def _download_bilibili(url: str, output_dir: Path) -> DownloadedVideo:
    apply_bilibili_dm_img_patch()
    video_id = extract_video_id(url, "bilibili")
    existing = _existing_file(output_dir, video_id or "")
    if existing:
        print(f"⏭️  已下载过 B 站视频：{existing.name}")
        return DownloadedVideo(
            video_path=existing,
            source_url=url,
            platform="bilibili",
            video_id=video_id or "",
        )
    return _download_with_ytdlp(url, "bilibili", output_dir)


# ---------------------------------------------------------------------------
# YouTube
# ---------------------------------------------------------------------------


def _download_youtube(url: str, output_dir: Path) -> DownloadedVideo:
    video_id = extract_video_id(url, "youtube")
    existing = _existing_file(output_dir, video_id or "")
    if existing:
        print(f"⏭️  已下载过 YouTube 视频：{existing.name}")
        return DownloadedVideo(
            video_path=existing,
            source_url=url,
            platform="youtube",
            video_id=video_id or "",
        )
    return _download_with_ytdlp(url, "youtube", output_dir)


